fn list_sum(l1: &List<Int>, l2: &List<Int>) -> Int {
    let mut total = 0
    let mut l1_head = l1
    let mut l2_head = l2
    while l1_head != nil() {
        match l1_head {
            Cons(x, xs) => {
                match l2_head {
                    Cons(y, ys) => {
                        total = total + x + y
                        l1_head = xs
                        l2_head = ys
                    },
                    _ => total == total + x,
                }
            },
            Nil => breakl,
        }
    }
    total
}

